#[test]
fn test_two_blocks_of_short_lines_far_apart_are_two_columns() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gfl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // D583 (smoke review A issue 14): an invoice's two blocks, Seller and Client, 238 pt apart, with 1 to 3 words a line (2.3 and 2.6 a line on average, short of three): two columns, not
    // lines that alternate. (The roles are body, body: the last fragment's role is 0.)
    ct_line(wd, ln, et, &crate::testport::text_blob("Seller:")[..], 7200, 10000);
    ct_line(wd, ln, et, &crate::testport::text_blob("Client:")[..], 40000, 10000);
    ct_line(wd, ln, et, &crate::testport::text_blob("Dunn Campbell")[..], 7200, 11400);
    ct_line(wd, ln, et, &crate::testport::text_blob("Ramirez Donaldson Lane")[..], 40000, 11400);
    ct_line(wd, ln, et, &crate::testport::text_blob("36709 Santiago Viaduct")[..], 7200, 12800);
    ct_line(wd, ln, et, &crate::testport::text_blob("567 Ortiz Valley")[..], 40000, 12800);
    ct_line(wd, ln, et, &crate::testport::text_blob("Dianaland MN 12512")[..], 7200, 14200);
    ct_line(wd, ln, et, &crate::testport::text_blob("Kellyfort GA 69454")[..], 40000, 14200);
    ct_line(wd, ln, et, &crate::testport::text_blob("Tax Id 986-74-6578")[..], 7200, 17000);
    ct_line(wd, ln, et, &crate::testport::text_blob("Tax Id 948-74-8143")[..], 40000, 17000);
    ct_line(wd, ln, et, &crate::testport::text_blob("IBAN GB37QZVP50159087754233")[..], 7200, 18400);
    crate::testport::assert_eq(ct_page(wd, et, ln, gfl, 0), 20 + rl_body(), "two body fragments");
}
